def avatar_data_uri() -> str:
    """Return only the bounded chosen JPEG; never accept a supplied data URI."""
    data = base64.b64decode(_JPEG_BASE64, validate=True)
    if len(data) != AVATAR_BYTES or hashlib.sha256(data).hexdigest() != AVATAR_SHA256:
        raise ValueError("trusted branding asset is invalid")
    return "data:image/jpeg;base64," + _JPEG_BASE64
